if (!window.renriCleanEmpty) {
    window.renriCleanEmpty = function(html) {
        return html
            .replace(/<p>\s*(<br\s*\/?>)?\s*<\/p>/gi, '')
            .replace(/^(\s*<br\s*\/?>)+/gi, '')
            .replace(/(\s*<br\s*\/?>)+$/gi, '')
            .replace(/(<br\s*\/?>(\s*)){3,}/gi, '<br>');
    };
}
if (!window.renriHideInbd) {
    window.renriHideInbd = function($target) {
        if (!$target || !$target.length) return;
        let html = $target.html();
        if (!html) return;
        const orig = html;
        html = html.replace(/\[INBD:[^\]]*\]/gi, '');
        if (html !== orig) {
            html = window.renriCleanEmpty ? window.renriCleanEmpty(html) : html;
            $target.html(html.trim());
        }
    };
}

(function() {
    const $ = window.jQuery;

    const MOD = {
        promptId: 'renri_infoboard_system',
        systemPrompt: 'End your messages with a information block STRICTLY in this exact format:\n[INBD: Name | Appearance & outfit detail | posture/activity | character state | NPC present | a short literary line fitting the current scene OR a message from the characters to us | recap ]\nCRITICAL: You MUST fill ALL fields in the [INBD:] block. If any information is unavailable or not applicable, write "N/A" in that field. Never skip or merge fields.\nGuidelines:\nRecap: Naturally recap what just happened in plain novel-outline style.\n- Normal scenes: ~60 words\n- NSFW scenes: ~30 words\nKeep it concise and fluent like fiction outline.\nLanguage for placeholders must match the language of the narrative.\nFill out a block for each main character in the scene. The AVATAR block will always come first, leave recap block N/A for them.',
        updatePrompt: '[System Note: Continue with INFOBOARD block(s) at the END of your message. Same [INBD: ...] format for each character.]',
        cssId: 'renri-infoboard-styles',
        expirationDepth: 7,
    };

    let TH = null;
    const _rendering = {};

    function esc(s) {
        return (s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
    }

    function isNA(s) {
        return !s || /^\s*n\/a\s*$/i.test((s||'').trim());
    }

    function buildCard(m) {
        var name  = (m[1]||'').trim();
        var recap = (m[7]||'').trim();

        var fieldDefs = [
            { key: 'Appearance', val: (m[2]||'').trim(), isQuote: false },
            { key: 'Posture',    val: (m[3]||'').trim(), isQuote: false },
            { key: 'State',      val: (m[4]||'').trim(), isQuote: false },
            { key: 'NPC',        val: (m[5]||'').trim(), isQuote: false },
            { key: 'Quote',      val: (m[6]||'').trim(), isQuote: true  },
        ];

        var rows = '';
        for (var j = 0; j < fieldDefs.length; j++) {
            var fd = fieldDefs[j];
            if (isNA(fd.val)) continue;
            var valHtml = fd.isQuote
                ? '<div class="rib-quote-val">' + esc(fd.val) + '</div>'
                : '<div class="rib-val">' + esc(fd.val) + '</div>';
            rows += '<div class="rib-key">' + fd.key + '</div>' + valHtml;
        }

        var recapHtml = '';
        if (!isNA(recap)) {
            recapHtml = '<div class="rib-recap">' +
                '<div class="rib-recap-label">Recap</div>' +
                '<div class="rib-recap-text">' + esc(recap) + '</div>' +
                '</div>';
        }

        return '<div class="rib-card">' +
            '<div class="rib-name">' + esc(name) + '</div>' +
            '<div class="rib-fields">' + rows + '</div>' +
            recapHtml +
            '</div>';
    }

    function buildBoard(matches) {
        var names = matches.map(function(m){ return (m[1]||'').trim(); }).join(', ');
        var cards = matches.map(buildCard).join('');
        return '<details class="rib-wrap">' +
            '<summary class="rib-toggle">' +
            '<span class="rib-toggle-icon">\u25b6</span>' +
            '<span class="rib-toggle-label">Infoboard</span>' +
            '<span class="rib-toggle-names">' + esc(names) + '</span>' +
            '</summary>' +
            '<div class="rib-cards">' + cards + '</div>' +
            '</details>';
    }

    function parseBlocks(raw) {
        var re = /\[INBD:\s*([^|\]]+)\|([^|\]]*)\|([^|\]]*)\|([^|\]]*)\|([^|\]]*)\|([^|\]]*)\|([^\]]*)\]/gi;
        var matches = [];
        var m;
        while ((m = re.exec(raw)) !== null) {
            matches.push(m);
        }
        return matches;
    }

    function getLastState() {
        var lastId = TH.getLastMessageId();
        if (lastId < 1) return null;
        var msgs = TH.getChatMessages('0-' + (lastId - 1));
        if (!msgs) return null;
        for (var i = msgs.length - 1; i >= 0; i--) {
            if (!msgs[i].message) continue;
            if (parseBlocks(msgs[i].message).length > 0) return true;
        }
        return null;
    }

    function injectPrompt(hasHistory) {
        var content = hasHistory ? MOD.updatePrompt : MOD.systemPrompt;
        TH.injectPrompts([{ id: MOD.promptId, position: 'in_chat', depth: 0, role: 'system', content: content, should_scan: false }], { once: true });
    }

    function renderVisual(messageId) {
        if (!TH) return;
        if (_rendering[messageId]) return;
        _rendering[messageId] = true;
        setTimeout(function() { delete _rendering[messageId]; }, 800);

        var msgs = TH.getChatMessages(messageId);
        if (!msgs || !msgs.length || !msgs[0].message) return;
        var raw = msgs[0].message;
        var matches = parseBlocks(raw);
        if (!matches.length) return;

        var $mes = TH.retrieveDisplayedMessage(messageId);
        if (!$mes || !$mes.length) return;
        var $target = $mes.find('.mes_text').length ? $mes.find('.mes_text') : $mes;
        var lastId = TH.getLastMessageId();
        var isExpired = (lastId - messageId) >= MOD.expirationDepth;

        $target.find('.rib-wrap').remove();
        if (window.renriHideInbd) window.renriHideInbd($target);
        $target.find('p, div, li').each(function() {
            var $el = $(this);
            if ($el.closest('.rib-wrap').length) return;
            if (/\[INBD:/i.test($el.text())) $el.remove();
        });
        var html = $target.html();
        html = window.renriCleanEmpty ? window.renriCleanEmpty(html) : html;
        $target.html(html.trim());

        if (!isExpired) {
            $target.append(buildBoard(matches));
        }
    }

    function initializeScript() {
        if (!window.TavernHelper || !window.tavern_events || typeof window.eventOn !== 'function') {
            setTimeout(initializeScript, 200);
            return;
        }
        TH = window.TavernHelper;
        var ev = window.tavern_events;

        if (!$('#' + MOD.cssId).length) {
            $('head').append('<style id="' + MOD.cssId + '">' + MOD.css + '</style>');
        }

        window.eventOn(ev.CHARACTER_MESSAGE_RENDERED, renderVisual);
        window.eventOn(ev.USER_MESSAGE_RENDERED, renderVisual);
        window.eventOn(ev.MESSAGE_EDITED,  function(id){ setTimeout(function(){ renderVisual(id); }, 100); });
        window.eventOn(ev.MESSAGE_UPDATED, function(id){ setTimeout(function(){ renderVisual(id); }, 100); });
        window.eventOn(ev.MESSAGE_SWIPED,  function(id){ setTimeout(function(){ renderVisual(id); }, 100); });

        var scan = function() {
            $('.mes').each(function() {
                var id = $(this).attr('mesid');
                if (id) renderVisual(Number(id));
            });
        };
        scan();

        window.eventOn(ev.CHAT_CHANGED,         function(){ setTimeout(scan, 500); });
        window.eventOn(ev.MORE_MESSAGES_LOADED, scan);
        window.eventOn(ev.GENERATION_AFTER_COMMANDS, function(){ injectPrompt(getLastState()); });
        window.eventOn(ev.GENERATION_ENDED,   function(){ setTimeout(function(){ var $l=$('.mes').last(); var id=$l.attr('mesid'); if(id) renderVisual(Number(id)); }, 400); });
        window.eventOn(ev.GENERATION_STOPPED, function(){ setTimeout(function(){ var $l=$('.mes').last(); var id=$l.attr('mesid'); if(id) renderVisual(Number(id)); }, 400); });

        console.log('[RenriInfoboard] init OK');
    }

    MOD.css = "@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@300;400;500;700&display=swap');.rib-wrap{display:flex;flex-direction:column;gap:0;font-family:'JetBrains Mono','Courier New',monospace;animation:rib-appear 0.35s cubic-bezier(0.16,1,0.3,1) both}@keyframes rib-appear{from{opacity:0;transform:translateY(-5px)}to{opacity:1;transform:translateY(0)}}.rib-toggle{display:flex;align-items:center;gap:8px;padding:7px 12px;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.09);cursor:pointer;user-select:none;list-style:none;transition:background 0.15s}.rib-toggle::-webkit-details-marker{display:none}.rib-toggle:hover{background:rgba(255,255,255,0.05)}.rib-toggle-icon{font-size:9px;color:rgba(255,255,255,0.25);transition:transform 0.2s;flex-shrink:0}details[open] .rib-toggle-icon{transform:rotate(90deg)}.rib-toggle-label{font-size:9px;font-weight:500;letter-spacing:0.12em;text-transform:uppercase;color:rgba(255,255,255,0.35);flex:1}.rib-toggle-names{font-size:9px;font-weight:400;color:rgba(255,255,255,0.2);letter-spacing:0.05em}.rib-cards{display:flex;flex-direction:column;border:1px solid rgba(255,255,255,0.09);border-top:none;overflow:hidden;background:rgba(255,255,255,0.02)}.rib-card{padding:10px 12px 11px;border-bottom:1px solid rgba(255,255,255,0.05);position:relative}.rib-card:last-child{border-bottom:none}.rib-name{font-size:11px;font-weight:700;color:rgba(255,255,255,0.80);letter-spacing:0.04em;margin-bottom:8px;display:flex;align-items:center;gap:6px}.rib-name::after{content:'';flex:1;height:1px;background:rgba(255,255,255,0.06)}.rib-fields{display:grid;grid-template-columns:auto 1fr;column-gap:10px;row-gap:4px;align-items:baseline}.rib-key{font-size:8px;font-weight:500;letter-spacing:0.1em;text-transform:uppercase;color:rgba(255,255,255,0.22);white-space:nowrap;padding-top:1px}.rib-val{font-size:10px;font-weight:300;color:rgba(255,255,255,0.62);line-height:1.45;overflow-wrap:anywhere}.rib-quote-val{font-size:10px;font-weight:300;color:rgba(255,255,255,0.40);font-style:italic;line-height:1.45;overflow-wrap:anywhere}.rib-recap{margin-top:8px;padding:7px 9px;background:rgba(255,255,255,0.025);border-left:2px solid rgba(255,255,255,0.08)}.rib-recap-label{font-size:8px;font-weight:500;letter-spacing:0.1em;text-transform:uppercase;color:rgba(255,255,255,0.18);margin-bottom:4px}.rib-recap-text{font-size:10px;font-weight:300;color:rgba(255,255,255,0.45);line-height:1.6;overflow-wrap:anywhere}";
    $(document).ready(initializeScript);
})();
